solution.solution.cpp:
#include <cstdint>
#include <cstring>
#include <vector>

using NTSTATUS = std::int32_t;
constexpr NTSTATUS STATUS_SUCCESS = 0;
constexpr NTSTATUS STATUS_INVALID_PARAMETER = static_cast<NTSTATUS>(0xC000000Du);
constexpr NTSTATUS STATUS_BUFFER_TOO_SMALL = static_cast<NTSTATUS>(0xC0000023u);
constexpr NTSTATUS STATUS_REVISION_MISMATCH = static_cast<NTSTATUS>(0xC0000059u);

struct Header { std::uint32_t size; std::uint32_t version; std::uint32_t count; std::uint32_t flags; };
struct Entry { std::uint32_t id; std::uint32_t value; };

NTSTATUS parseRequest(const std::uint8_t* input, std::uint32_t inputLength, std::vector<Entry>& out)
{
    out.clear();
    if (!input || inputLength < sizeof(Header)) return STATUS_BUFFER_TOO_SMALL;
    Header h;
    std::memcpy(&h, input, sizeof(h));                                    // read once
    if (h.size != sizeof(Header)) return STATUS_INVALID_PARAMETER;
    if (h.version != 1 && h.version != 2) return STATUS_REVISION_MISMATCH;
    if (h.flags & ~3u) return STATUS_INVALID_PARAMETER;
    const std::uint32_t room{ inputLength - static_cast<std::uint32_t>(sizeof(Header)) };
    if (h.count > room / sizeof(Entry)) return STATUS_INVALID_PARAMETER;  // no multiplication, no overflow
    if (h.version == 1 && h.count > 16) return STATUS_INVALID_PARAMETER;
    out.resize(h.count);
    if (h.count) std::memcpy(out.data(), input + sizeof(Header), h.count * sizeof(Entry));
    return STATUS_SUCCESS;
}

unitTests:
std::vector<std::uint8_t> request(std::uint32_t size, std::uint32_t version, std::uint32_t count, std::uint32_t flags, std::uint32_t entries, std::uint32_t extra = 0) {
    std::vector<std::uint8_t> b(16 + entries * 8 + extra, 0);
    const std::uint32_t h[4]{ size, version, count, flags }; std::memcpy(b.data(), h, 16);
    for (std::uint32_t i = 0; i < entries; ++i) { const std::uint32_t e[2]{ i + 1, (i + 1) * 100 }; std::memcpy(b.data() + 16 + i * 8, e, 8); }
    return b;
}
TEST("a good request") {
    std::vector<Entry> out; auto b = request(16, 2, 3, 1, 3, 5);
    CHECK_EQ(parseRequest(b.data(), static_cast<std::uint32_t>(b.size()), out), STATUS_SUCCESS); CHECK_EQ(out.size(), std::size_t{ 3 }); CHECK_EQ(out[2].value, 300u);
    auto empty = request(16, 1, 0, 0, 0); CHECK_EQ(parseRequest(empty.data(), 16, out), STATUS_SUCCESS); CHECK(out.empty());
}
TEST("short and wrong headers") {
    std::vector<Entry> out; auto b = request(16, 2, 0, 0, 0);
    CHECK_EQ(parseRequest(b.data(), 15, out), STATUS_BUFFER_TOO_SMALL); CHECK_EQ(parseRequest(nullptr, 0, out), STATUS_BUFFER_TOO_SMALL);
    auto s = request(20, 2, 0, 0, 0, 4); CHECK_EQ(parseRequest(s.data(), 20, out), STATUS_INVALID_PARAMETER);
    auto v = request(16, 3, 0, 0, 0); CHECK_EQ(parseRequest(v.data(), 16, out), STATUS_REVISION_MISMATCH);
    auto f = request(16, 2, 0, 4, 0); CHECK_EQ(parseRequest(f.data(), 16, out), STATUS_INVALID_PARAMETER);
}
TEST("counts that lie") {
    std::vector<Entry> out;
    auto b = request(16, 2, 4, 0, 3); CHECK_EQ(parseRequest(b.data(), static_cast<std::uint32_t>(b.size()), out), STATUS_INVALID_PARAMETER); CHECK(out.empty());
    auto huge = request(16, 2, 0x20000001u, 0, 1); CHECK_EQ(parseRequest(huge.data(), static_cast<std::uint32_t>(huge.size()), out), STATUS_INVALID_PARAMETER);
    auto many = request(16, 1, 17, 0, 17); CHECK_EQ(parseRequest(many.data(), static_cast<std::uint32_t>(many.size()), out), STATUS_INVALID_PARAMETER);
    auto ok2 = request(16, 2, 17, 0, 17); CHECK_EQ(parseRequest(ok2.data(), static_cast<std::uint32_t>(ok2.size()), out), STATUS_SUCCESS);
}
TEST("unaligned input") {
    std::vector<Entry> out; auto b = request(16, 2, 2, 0, 2); std::vector<std::uint8_t> shifted(b.size() + 1); std::memcpy(shifted.data() + 1, b.data(), b.size());
    CHECK_EQ(parseRequest(shifted.data() + 1, static_cast<std::uint32_t>(b.size()), out), STATUS_SUCCESS); CHECK_EQ(out[1].id, 2u);
}

